/* Select-only combobox. Native select remains the form value; no OS popup. */
(()=>{'use strict';let active=null,seq=0;const all=new Set();const close=()=>{if(!active)return;active.menu.hidden=true;active.button.setAttribute('aria-expanded','false');active.button.removeAttribute('aria-activedescendant');active=null};window.toktokCloseSelects=()=>{close();all.forEach(x=>x.menu.remove());all.clear()};
function enhance(select){if(select.dataset.enhanced)return;const nativeLabels=Array.from(select.labels||[]);select.dataset.enhanced='true';const id='tok-select-'+(++seq),wrapper=document.createElement('div'),button=document.createElement('button'),menu=document.createElement('div');wrapper.className='tok-select';select.after(wrapper);wrapper.append(select);select.hidden=true;select.tabIndex=-1;button.type='button';button.className='tok-select-button';button.id=id;nativeLabels.forEach(label=>label.htmlFor=id);button.setAttribute('role','combobox');button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls',id+'-list');button.disabled=select.disabled;let label=select.getAttribute('aria-label')||select.closest('label')?.childNodes[0]?.textContent?.trim()||'선택';button.setAttribute('aria-label',label);menu.id=id+'-list';menu.className='tok-select-menu';menu.setAttribute('role','listbox');menu.setAttribute('aria-label',label);menu.hidden=true;document.body.append(menu);wrapper.append(button);const options=Array.from(select.options);let index=Math.max(0,select.selectedIndex),buffer='',lastType=0;const x={button,menu,select};all.add(x);function sync(){index=Math.max(0,select.selectedIndex);button.setAttribute('aria-label',label+': '+(options[index]?.textContent||'선택해주세요'));button.innerHTML='<span>'+escapeText(options[index]?.textContent||'선택해주세요')+'</span><svg aria-hidden="true" viewBox="0 0 20 20"><path d="m5 7 5 5 5-5"/></svg>';menu.innerHTML=options.map((o,i)=>`<div id="${id}-option-${i}" class="tok-select-option" role="option" aria-selected="${i===select.selectedIndex}" ${o.disabled?'aria-disabled="true"':''} data-index="${i}"><span>${escapeText(o.textContent)}</span><span class="option-tick" aria-hidden="true">${i===select.selectedIndex?'✓':''}</span></div>`).join('');menu.querySelectorAll('[role=option]').forEach(o=>{o.addEventListener('mousedown',e=>e.preventDefault());o.addEventListener('click',()=>{const n=Number(o.dataset.index);if(!options[n].disabled)commit(n)})})}function position(){const r=button.getBoundingClientRect(),width=Math.min(Math.max(r.width,220),innerWidth-32);menu.style.width=width+'px';menu.style.left=Math.max(16,Math.min(r.left,innerWidth-width-16))+'px';const below=innerHeight-r.bottom-12,above=r.top-12,up=below<170&&above>below;menu.style.maxHeight=Math.max(80,Math.min(280,up?above:below))+'px';menu.style.top='auto';menu.style.bottom='auto';if(up)menu.style.bottom=(innerHeight-r.top+7)+'px';else menu.style.top=(r.bottom+7)+'px'}function highlight(n){index=Math.max(0,Math.min(options.length-1,n));menu.querySelectorAll('[role=option]').forEach((o,i)=>o.classList.toggle('is-active',i===index));button.setAttribute('aria-activedescendant',id+'-option-'+index);menu.children[index]?.scrollIntoView({block:'nearest'})}function open(){if(button.disabled)return;close();active=x;menu.hidden=false;button.setAttribute('aria-expanded','true');position();highlight(select.selectedIndex)}function commit(n){if(options[n]?.disabled)return;select.selectedIndex=n;close();sync();button.focus();select.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}));if(!document.contains(button)){const fresh=select.id?document.getElementById(select.id):select.name?document.querySelector('select[name="'+select.name+'"]'):null;fresh?.parentElement?.querySelector('.tok-select-button')?.focus()}}button.addEventListener('click',()=>active===x?close():open());button.addEventListener('keydown',e=>{const isOpen=active===x;if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();if(!isOpen)open();highlight(e.key==='Home'?0:e.key==='End'?options.length-1:index+(e.key==='ArrowDown'?1:-1));return}if(e.key==='Enter'||e.key===' '){e.preventDefault();if(isOpen)commit(index);else open();return}if(e.key==='Escape'){if(isOpen){e.preventDefault();e.stopPropagation();close()}return}if(e.key==='Tab'){if(isOpen)commit(index);return}if(e.key.length===1&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();if(Date.now()-lastType>700)buffer='';buffer+=e.key.toLocaleLowerCase();lastType=Date.now();if(!isOpen)open();const n=options.findIndex(o=>o.textContent.trim().toLocaleLowerCase().startsWith(buffer));if(n>=0)highlight(n)}});x.position=position;sync()}
function escapeText(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}window.toktokEnhanceSelects=()=>document.querySelectorAll('#app select').forEach(enhance);document.addEventListener('pointerdown',e=>{if(active&&!active.menu.contains(e.target)&&!active.button.contains(e.target))close()});window.addEventListener('resize',()=>active?.position());window.addEventListener('scroll',e=>{if(active&&!active.menu.contains(e.target))active.position()},true);window.toktokEnhanceSelects();})();
